#include <math.h>
#include <string.h>
#include <stdlib.h>

static const double PAYOFFS[6] = {660.0, 150.0, -1040.0, -4100.0, -9200.0, -14300.0};
static const double POS_PAYOFFS[6] = {660.0, 150.0, 0.0, 0.0, 0.0, 0.0};
static const double NEG_LOSSES[6] = {0.0, 0.0, 1040.0, 4100.0, 9200.0, 14300.0};
static const double CHECK_COST = 20.0;

// Combinatorial number system to map sorted tuple of length d <= 6 with elements in 0..17 to unique int
static int binom[26][9];
static int level_offset[8];
static int initialized = 0;

void init_tables(void) {
    if (initialized) return;
    for (int n = 0; n <= 25; n++) {
        binom[n][0] = 1;
        for (int k = 1; k <= 8 && k <= n; k++) {
            binom[n][k] = binom[n-1][k-1] + binom[n-1][k];
        }
    }
    level_offset[0] = 0;
    for (int d = 1; d <= 7; d++) {
        level_offset[d] = level_offset[d-1] + binom[18 + d - 1][d - 1];
    }
    initialized = 1;
}

// Tuple of length d (0 <= a[0] <= a[1] <= ... <= a[d-1] < 18)
static inline int encode_tuple(const int *a, int d) {
    int idx = level_offset[d];
    for (int i = 0; i < d; i++) {
        // strictly increasing b[i] = a[i] + i
        int bi = a[i] + i;
        idx += binom[bi][i + 1];
    }
    return idx;
}

// Solve using unnormalized weights w[0..5]
// Returns unnormalized value V(w) = sum(w) * V(w / sum(w))
static double solve_rec(
    const int *a, int d, int max_steps,
    const double *w,
    const double L[18][6],
    double *memo
) {
    double sum_w = w[0] + w[1] + w[2] + w[3] + w[4] + w[5];
    double app_val = w[0]*PAYOFFS[0] + w[1]*PAYOFFS[1] + w[2]*PAYOFFS[2]
                   + w[3]*PAYOFFS[3] + w[4]*PAYOFFS[4] + w[5]*PAYOFFS[5];
    double stop_val = app_val > 0.0 ? app_val : 0.0;
    int rem = max_steps - d;
    if (rem <= 0) {
        return stop_val;
    }
    double cost_w = CHECK_COST * sum_w;
    double pos_w = w[0]*POS_PAYOFFS[0] + w[1]*POS_PAYOFFS[1];
    if (pos_w - cost_w <= stop_val) {
        return stop_val;
    }
    double neg_w = w[2]*NEG_LOSSES[2] + w[3]*NEG_LOSSES[3] + w[4]*NEG_LOSSES[4] + w[5]*NEG_LOSSES[5];
    if (neg_w <= cost_w) {
        return stop_val;
    }

    if (rem == 1) {
        // 1 step lookahead directly without recursion
        double best = stop_val;
        for (int k = 0; k < 3; k++) {
            double ev = -cost_w;
            int base = k * 6;
            for (int b = 0; b < 6; b++) {
                const double *lb = L[base + b];
                double av = w[0]*lb[0]*PAYOFFS[0] + w[1]*lb[1]*PAYOFFS[1]
                          + w[2]*lb[2]*PAYOFFS[2] + w[3]*lb[3]*PAYOFFS[3]
                          + w[4]*lb[4]*PAYOFFS[4] + w[5]*lb[5]*PAYOFFS[5];
                if (av > 0.0) ev += av;
            }
            if (ev > best) best = ev;
        }
        return best;
    }

    int idx = encode_tuple(a, d);
    if (memo[idx] >= -0.5) {
        return memo[idx];
    }

    double best = stop_val;
    int next_a[8];
    for (int k = 0; k < 3; k++) {
        double ev = -cost_w;
        int base = k * 6;
        for (int b = 0; b < 6; b++) {
            int obs = base + b;
            const double *lb = L[obs];
            double w_next[6];
            double s_next = 0.0;
            for (int s = 0; s < 6; s++) {
                w_next[s] = w[s] * lb[s];
                s_next += w_next[s];
            }
            if (s_next > 1e-15) {
                // insert obs into sorted array a[0..d-1]
                int pos = 0;
                while (pos < d && a[pos] < obs) {
                    next_a[pos] = a[pos];
                    pos++;
                }
                next_a[pos] = obs;
                for (int j = pos; j < d; j++) {
                    next_a[j + 1] = a[j];
                }
                ev += solve_rec(next_a, d + 1, max_steps, w_next, L, memo);
            }
        }
        if (ev > best) best = ev;
    }
    memo[idx] = best;
    return best;
}

// Compute V* and Q-values [approve, decline, check_0, check_1, check_2] at root belief `prior`
// with `rem_steps` remaining (up to 8)
void solve_belief(
    const double *prior,
    int rem_steps,
    const double *P_flat, // (3, 6, 6): check, seg, band
    double *q_out         // length 5: [approve, decline, bureau, income, bank]
) {
    init_tables();
    double L[18][6];
    for (int k = 0; k < 3; k++) {
        for (int s = 0; s < 6; s++) {
            for (int b = 0; b < 6; b++) {
                L[k * 6 + b][s] = P_flat[k * 36 + s * 6 + b];
            }
        }
    }
    double sum_w = 0.0;
    double w[6];
    for (int s = 0; s < 6; s++) {
        w[s] = prior[s];
        sum_w += w[s];
    }
    for (int s = 0; s < 6; s++) w[s] /= sum_w;

    double app_val = 0.0;
    for (int s = 0; s < 6; s++) app_val += w[s] * PAYOFFS[s];
    q_out[0] = app_val;
    q_out[1] = 0.0;

    if (rem_steps <= 0) {
        q_out[2] = -1e9;
        q_out[3] = -1e9;
        q_out[4] = -1e9;
        return;
    }

    int total_states = level_offset[7]; // 134596
    double *memo = (double *)malloc(sizeof(double) * total_states);
    for (int i = 0; i < total_states; i++) memo[i] = -1.0;

    int next_a[1];
    for (int k = 0; k < 3; k++) {
        double ev = -CHECK_COST;
        int base = k * 6;
        for (int b = 0; b < 6; b++) {
            int obs = base + b;
            double w_next[6];
            double s_next = 0.0;
            for (int s = 0; s < 6; s++) {
                w_next[s] = w[s] * L[obs][s];
                s_next += w_next[s];
            }
            if (s_next > 1e-15) {
                next_a[0] = obs;
                ev += solve_rec(next_a, 1, rem_steps, w_next, L, memo);
            }
        }
        q_out[2 + k] = ev;
    }
    free(memo);
}

