}

static double eval_policy_rec(
    const int *a, int d, int max_steps,
    const double *w_hat,
    const double *w_true,
    const double L_hat[18][6],
    const double L_true[18][6],
    double *memo_hat,
    int *act_memo
) {
    double sum_true = w_true[0] + w_true[1] + w_true[2] + w_true[3] + w_true[4] + w_true[5];
    if (sum_true <= 1e-15) return 0.0;
    double app_true = w_true[0]*PAYOFFS[0] + w_true[1]*PAYOFFS[1] + w_true[2]*PAYOFFS[2]
                    + w_true[3]*PAYOFFS[3] + w_true[4]*PAYOFFS[4] + w_true[5]*PAYOFFS[5];

    double sum_hat = w_hat[0] + w_hat[1] + w_hat[2] + w_hat[3] + w_hat[4] + w_hat[5];
    double app_hat = w_hat[0]*PAYOFFS[0] + w_hat[1]*PAYOFFS[1] + w_hat[2]*PAYOFFS[2]
                   + w_hat[3]*PAYOFFS[3] + w_hat[4]*PAYOFFS[4] + w_hat[5]*PAYOFFS[5];
    double stop_hat = app_hat > 0.0 ? app_hat : 0.0;
    int stop_act = app_hat > 0.0 ? 0 : 1;

    int rem = max_steps - d;
    if (rem <= 0) {
        return stop_act == 0 ? app_true : 0.0;
    }

    int act = stop_act;
    if (rem == 1) {
        double cost_hat = CHECK_COST * sum_hat;
        double best = stop_hat;
        for (int k = 0; k < 3; k++) {
            double ev = -cost_hat;
            int base = k * 6;
            for (int b = 0; b < 6; b++) {
                const double *lb = L_hat[base + b];
                double av = w_hat[0]*lb[0]*PAYOFFS[0] + w_hat[1]*lb[1]*PAYOFFS[1]
                          + w_hat[2]*lb[2]*PAYOFFS[2] + w_hat[3]*lb[3]*PAYOFFS[3]
                          + w_hat[4]*lb[4]*PAYOFFS[4] + w_hat[5]*lb[5]*PAYOFFS[5];
                if (av > 0.0) ev += av;
            }
            if (ev > best) {
                best = ev;
                act = 2 + k;
            }
        }
    } else {
        int idx = encode_tuple(a, d);
        if (memo_hat[idx] < -0.5) {
            solve_rec_with_action(a, d, max_steps, w_hat, L_hat, memo_hat, act_memo);
        }
        act = act_memo[idx];
    }

    if (act == 0) return app_true;
    if (act == 1) return 0.0;

    int k = act - 2;
    double ev_true = -CHECK_COST * sum_true;
    int base = k * 6;
    int next_a[8];
    for (int b = 0; b < 6; b++) {
        int obs = base + b;
        double wh_next[6], wt_next[6];
        double st_next = 0.0;
        for (int s = 0; s < 6; s++) {
            wh_next[s] = w_hat[s] * L_hat[obs][s];
            wt_next[s] = w_true[s] * L_true[obs][s];
            st_next += wt_next[s];
        }
        if (st_next > 1e-15) {
            int pos = 0;
            while (pos < d && a[pos] < obs) {
                next_a[pos] = a[pos];
                pos++;
            }
            next_a[pos] = obs;
            for (int j = pos; j < d; j++) {
                next_a[j + 1] = a[j];
            }
            ev_true += eval_policy_rec(next_a, d + 1, max_steps, wh_next, wt_next, L_hat, L_true, memo_hat, act_memo);
        }
    }
    return ev_true;
}

double eval_policy_under_truth(
    const double *prior,
    int rem_steps,
    const double *P_hat_flat,
    const double *P_true_flat
) {
    init_tables();
    double L_hat[18][6], L_true[18][6];
    for (int k = 0; k < 3; k++) {
        for (int s = 0; s < 6; s++) {
            for (int b = 0; b < 6; b++) {
                L_hat[k * 6 + b][s] = P_hat_flat[k * 36 + s * 6 + b];
                L_true[k * 6 + b][s] = P_true_flat[k * 36 + s * 6 + b];
            }
        }
    }
    int total_states = level_offset[7];
    double *memo_hat = (double *)malloc(sizeof(double) * total_states);
    int *act_memo = (int *)malloc(sizeof(int) * total_states);
    for (int i = 0; i < total_states; i++) {
        memo_hat[i] = -1.0;
        act_memo[i] = 1;
    }
    int empty_a[1] = {0};
    double val = eval_policy_rec(empty_a, 0, rem_steps, prior, prior, L_hat, L_true, memo_hat, act_memo);
    free(memo_hat);
    free(act_memo);
    return val;
}

