#include <math.h>
#include <string.h>
#include <stdlib.h>

static const double PAYOFFS[6] = {660.0, 150.0, -1040.0, -4100.0, -9200.0, -14300.0};
static const double POS_PAYOFFS[6] = {660.0, 150.0, 0.0, 0.0, 0.0, 0.0};
static const double NEG_LOSSES[6] = {0.0, 0.0, 1040.0, 4100.0, 9200.0, 14300.0};
static const double CHECK_COST = 20.0;

static int binom[26][9];
static int level_offset[8];
static int initialized = 0;

void init_tables(void) {
    if (initialized) return;
    for (int n = 0; n <= 25; n++) {
        binom[n][0] = 1;
        for (int k = 1; k <= 8 && k <= n; k++) {
            binom[n][k] = binom[n-1][k-1] + binom[n-1][k];
        }
    }
    level_offset[0] = 0;
    for (int d = 1; d <= 7; d++) {
        level_offset[d] = level_offset[d-1] + binom[18 + d - 1][d - 1];
    }
    initialized = 1;
}

static inline int encode_tuple(const int *a, int d) {
    int idx = level_offset[d];
    for (int i = 0; i < d; i++) {
        int bi = a[i] + i;
        idx += binom[bi][i + 1];
    }
    return idx;
}

static inline double upper_bound_state(const double *w, int rem) {
    double sum_w = w[0] + w[1] + w[2] + w[3] + w[4] + w[5];
    double app_val = w[0]*PAYOFFS[0] + w[1]*PAYOFFS[1] + w[2]*PAYOFFS[2]
                   + w[3]*PAYOFFS[3] + w[4]*PAYOFFS[4] + w[5]*PAYOFFS[5];
    double stop_val = app_val > 0.0 ? app_val : 0.0;
    if (rem <= 0) return stop_val;
    double cost_w = CHECK_COST * sum_w;
    double pos_w = w[0]*POS_PAYOFFS[0] + w[1]*POS_PAYOFFS[1];
    double perf_val = pos_w - cost_w;
    if (perf_val <= stop_val) return stop_val;
    double neg_w = w[2]*NEG_LOSSES[2] + w[3]*NEG_LOSSES[3] + w[4]*NEG_LOSSES[4] + w[5]*NEG_LOSSES[5];
    if (neg_w <= cost_w) return stop_val;
    // Both perf_val and app_val + neg_w - cost_w are valid upper bounds; actually app_val + neg_w == pos_w!
    return perf_val;
}

static double solve_rec_with_action(
    const int *a, int d, int max_steps,
    const double *w,
    const double L[18][6],
    double *memo,
    int *act_memo
) {
    double sum_w = w[0] + w[1] + w[2] + w[3] + w[4] + w[5];
    double app_val = w[0]*PAYOFFS[0] + w[1]*PAYOFFS[1] + w[2]*PAYOFFS[2]
                   + w[3]*PAYOFFS[3] + w[4]*PAYOFFS[4] + w[5]*PAYOFFS[5];
    double stop_val = app_val > 0.0 ? app_val : 0.0;
    int stop_act = app_val > 0.0 ? 0 : 1;
    int rem = max_steps - d;
    if (rem <= 0) {
        return stop_val;
    }
    int idx = (rem == 1) ? -1 : encode_tuple(a, d);
    if (idx >= 0 && memo[idx] >= -0.5) {
        return memo[idx];
    }

    double cost_w = CHECK_COST * sum_w;
    double pos_w = w[0]*POS_PAYOFFS[0] + w[1]*POS_PAYOFFS[1];
    if (pos_w - cost_w <= stop_val) {
        if (idx >= 0) { memo[idx] = stop_val; act_memo[idx] = stop_act; }
        return stop_val;
    }
    double neg_w = w[2]*NEG_LOSSES[2] + w[3]*NEG_LOSSES[3] + w[4]*NEG_LOSSES[4] + w[5]*NEG_LOSSES[5];
    if (neg_w <= cost_w) {
        if (idx >= 0) { memo[idx] = stop_val; act_memo[idx] = stop_act; }
        return stop_val;
    }

    if (rem == 1) {
        double best = stop_val;
        for (int k = 0; k < 3; k++) {
            double ev = -cost_w;
            int base = k * 6;
            for (int b = 0; b < 6; b++) {
                const double *lb = L[base + b];
                double av = w[0]*lb[0]*PAYOFFS[0] + w[1]*lb[1]*PAYOFFS[1]
                          + w[2]*lb[2]*PAYOFFS[2] + w[3]*lb[3]*PAYOFFS[3]
                          + w[4]*lb[4]*PAYOFFS[4] + w[5]*lb[5]*PAYOFFS[5];
                if (av > 0.0) ev += av;
            }
            if (ev > best) best = ev;
        }
        return best;
    }

    double best = stop_val;
    int best_act = stop_act;
    int next_a[8];
    // Evaluate checks in order: income (1), bank (2), bureau (0)
    static const int K_ORDER[3] = {1, 2, 0};
    for (int ki = 0; ki < 3; ki++) {
        int k = K_ORDER[ki];
        int base = k * 6;
        double w_next_all[6][6];
        double s_next_all[6];
        double ub_all[6];
        double ev_ub = -cost_w;
        for (int b = 0; b < 6; b++) {
            const double *lb = L[base + b];
            double s_next = 0.0;
            for (int s = 0; s < 6; s++) {
                double wn = w[s] * lb[s];
                w_next_all[b][s] = wn;
                s_next += wn;
            }
            s_next_all[b] = s_next;
            if (s_next > 1e-15) {
                ub_all[b] = upper_bound_state(w_next_all[b], rem - 1);
                ev_ub += ub_all[b];
            } else {
                ub_all[b] = 0.0;
            }
        }
        // Alpha-beta pruning! If even the sum of upper bounds across all 6 bands cannot beat `best`, skip!
        if (ev_ub <= best + 1e-12 && act_memo == NULL) {
            continue;
        }
        double ev = -cost_w;
        int pruned = 0;
        // Evaluate from band 5 down to band 0 (highest variance/value bands first)
        for (int b = 5; b >= 0; b--) {
            if (s_next_all[b] > 1e-15) {
                int obs = base + b;
                int pos = 0;
                while (pos < d && a[pos] < obs) {
                    next_a[pos] = a[pos];
                    pos++;
                }
                next_a[pos] = obs;
                for (int j = pos; j < d; j++) {
                    next_a[j + 1] = a[j];
                }
                double val_b = solve_rec_with_action(next_a, d + 1, max_steps, w_next_all[b], L, memo, act_memo);
                ev += val_b;
                ev_ub += (val_b - ub_all[b]);
                if (ev_ub <= best + 1e-12 && act_memo == NULL) {
                    pruned = 1;
                    break;
                }
            }
        }
        if (!pruned && ev > best) {
            best = ev;
            best_act = 2 + k;
        }
    }
    memo[idx] = best;
    if (act_memo != NULL) act_memo[idx] = best_act;
    return best;
}

void solve_belief(
    const double *prior,
    int rem_steps,
    const double *P_flat,
    double *q_out
) {
    init_tables();
    double L[18][6];
    for (int k = 0; k < 3; k++) {
        for (int s = 0; s < 6; s++) {
            for (int b = 0; b < 6; b++) {
                L[k * 6 + b][s] = P_flat[k * 36 + s * 6 + b];
            }
        }
    }
    double sum_w = 0.0;
    double w[6];
    for (int s = 0; s < 6; s++) {
        w[s] = prior[s];
        sum_w += w[s];
    }
    for (int s = 0; s < 6; s++) w[s] /= sum_w;

    double app_val = 0.0;
    for (int s = 0; s < 6; s++) app_val += w[s] * PAYOFFS[s];
    q_out[0] = app_val;
    q_out[1] = 0.0;

    if (rem_steps <= 0) {
        q_out[2] = -1e9;
        q_out[3] = -1e9;
        q_out[4] = -1e9;
        return;
    }

    int total_states = level_offset[7];
    double *memo = (double *)malloc(sizeof(double) * total_states);
    for (int i = 0; i < total_states; i++) memo[i] = -1.0;

    int next_a[1];
    for (int k = 0; k < 3; k++) {
        double ev = -CHECK_COST;
        int base = k * 6;
        for (int b = 0; b < 6; b++) {
            int obs = base + b;
            double w_next[6];
            double s_next = 0.0;
            for (int s = 0; s < 6; s++) {
                w_next[s] = w[s] * L[obs][s];
                s_next += w_next[s];
            }
            if (s_next > 1e-15) {
                next_a[0] = obs;
                ev += solve_rec_with_action(next_a, 1, rem_steps, w_next, L, memo, NULL);
            }
        }
        q_out[2 + k] = ev;
    }
    free(memo);
}

static double eval_policy_rec(
    const int *a, int d, int max_steps,
    const double *w_hat,
    const double *w_true,
    const double L_hat[18][6],
    const double L_true[18][6],
    double *memo_hat,
    int *act_memo
) {
    double sum_true = w_true[0] + w_true[1] + w_true[2] + w_true[3] + w_true[4] + w_true[5];
    if (sum_true <= 1e-15) return 0.0;
    double app_true = w_true[0]*PAYOFFS[0] + w_true[1]*PAYOFFS[1] + w_true[2]*PAYOFFS[2]
                    + w_true[3]*PAYOFFS[3] + w_true[4]*PAYOFFS[4] + w_true[5]*PAYOFFS[5];

    double sum_hat = w_hat[0] + w_hat[1] + w_hat[2] + w_hat[3] + w_hat[4] + w_hat[5];
    double app_hat = w_hat[0]*PAYOFFS[0] + w_hat[1]*PAYOFFS[1] + w_hat[2]*PAYOFFS[2]
                   + w_hat[3]*PAYOFFS[3] + w_hat[4]*PAYOFFS[4] + w_hat[5]*PAYOFFS[5];
    double stop_hat = app_hat > 0.0 ? app_hat : 0.0;
    int stop_act = app_hat > 0.0 ? 0 : 1;

    int rem = max_steps - d;
    if (rem <= 0) {
        return stop_act == 0 ? app_true : 0.0;
    }

    int act = stop_act;
    if (rem == 1) {
        double cost_hat = CHECK_COST * sum_hat;
        double best = stop_hat;
        for (int k = 0; k < 3; k++) {
            double ev = -cost_hat;
            int base = k * 6;
            for (int b = 0; b < 6; b++) {
                const double *lb = L_hat[base + b];
                double av = w_hat[0]*lb[0]*PAYOFFS[0] + w_hat[1]*lb[1]*PAYOFFS[1]
                          + w_hat[2]*lb[2]*PAYOFFS[2] + w_hat[3]*lb[3]*PAYOFFS[3]
                          + w_hat[4]*lb[4]*PAYOFFS[4] + w_hat[5]*lb[5]*PAYOFFS[5];
                if (av > 0.0) ev += av;
            }
            if (ev > best) {
                best = ev;
                act = 2 + k;
            }
        }
    } else {
        int idx = encode_tuple(a, d);
        if (act_memo[idx] == -1) {
            // Compute best action at this state using memo_hat (where memo_hat values are exact via alpha-beta!)
            double cost_hat = CHECK_COST * sum_hat;
            double pos_w = w_hat[0]*POS_PAYOFFS[0] + w_hat[1]*POS_PAYOFFS[1];
            double neg_w = w_hat[2]*NEG_LOSSES[2] + w_hat[3]*NEG_LOSSES[3] + w_hat[4]*NEG_LOSSES[4] + w_hat[5]*NEG_LOSSES[5];
            if (pos_w - cost_hat <= stop_hat || neg_w <= cost_hat) {
                act_memo[idx] = stop_act;
            } else {
                double best = stop_hat;
                int best_a = stop_act;
                int next_a[8];
                static const int K_ORDER[3] = {1, 2, 0};
                for (int ki = 0; ki < 3; ki++) {
                    int k = K_ORDER[ki];
                    int base = k * 6;
                    double w_next_all[6][6];
                    double s_next_all[6];
                    double ub_all[6];
                    double ev_ub = -cost_hat;
                    for (int b = 0; b < 6; b++) {
                        const double *lb = L_hat[base + b];
                        double s_next = 0.0;
                        for (int s = 0; s < 6; s++) {
                            double wn = w_hat[s] * lb[s];
                            w_next_all[b][s] = wn;
                            s_next += wn;
                        }
                        s_next_all[b] = s_next;
                        if (s_next > 1e-15) {
                            ub_all[b] = upper_bound_state(w_next_all[b], rem - 1);
                            ev_ub += ub_all[b];
                        } else {
                            ub_all[b] = 0.0;
                        }
                    }
                    if (ev_ub <= best + 1e-12) continue;
                    double ev = -cost_hat;
                    int pruned = 0;
                    for (int b = 5; b >= 0; b--) {
                        if (s_next_all[b] > 1e-15) {
                            int obs = base + b;
                            int pos = 0;
                            while (pos < d && a[pos] < obs) {
                                next_a[pos] = a[pos];
                                pos++;
                            }
                            next_a[pos] = obs;
                            for (int j = pos; j < d; j++) {
                                next_a[j + 1] = a[j];
                            }
                            double val_b = solve_rec_with_action(next_a, d + 1, max_steps, w_next_all[b], L_hat, memo_hat, NULL);
                            ev += val_b;
                            ev_ub += (val_b - ub_all[b]);
                            if (ev_ub <= best + 1e-12) {
                                pruned = 1;
                                break;
                            }
                        }
                    }
                    if (!pruned && ev > best) {
                        best = ev;
                        best_a = 2 + k;
                    }
                }
                act_memo[idx] = best_a;
            }
        }
        act = act_memo[idx];
    }

    if (act == 0) return app_true;
    if (act == 1) return 0.0;

    int k = act - 2;
    double ev_true = -CHECK_COST * sum_true;
    int base = k * 6;
    int next_a[8];
    for (int b = 0; b < 6; b++) {
        int obs = base + b;
        double wh_next[6], wt_next[6];
        double st_next = 0.0;
        for (int s = 0; s < 6; s++) {
            wh_next[s] = w_hat[s] * L_hat[obs][s];
            wt_next[s] = w_true[s] * L_true[obs][s];
            st_next += wt_next[s];
        }
        if (st_next > 1e-15) {
            int pos = 0;
            while (pos < d && a[pos] < obs) {
                next_a[pos] = a[pos];
                pos++;
            }
            next_a[pos] = obs;
            for (int j = pos; j < d; j++) {
                next_a[j + 1] = a[j];
            }
            ev_true += eval_policy_rec(next_a, d + 1, max_steps, wh_next, wt_next, L_hat, L_true, memo_hat, act_memo);
        }
    }
    return ev_true;
}

double eval_policy_under_truth(
    const double *prior,
    int rem_steps,
    const double *P_hat_flat,
    const double *P_true_flat
) {
    init_tables();
    double L_hat[18][6], L_true[18][6];
    for (int k = 0; k < 3; k++) {
        for (int s = 0; s < 6; s++) {
            for (int b = 0; b < 6; b++) {
                L_hat[k * 6 + b][s] = P_hat_flat[k * 36 + s * 6 + b];
                L_true[k * 6 + b][s] = P_true_flat[k * 36 + s * 6 + b];
            }
        }
    }
    int total_states = level_offset[7];
    double *memo_hat = (double *)malloc(sizeof(double) * total_states);
    int *act_memo = (int *)malloc(sizeof(int) * total_states);
    for (int i = 0; i < total_states; i++) {
        memo_hat[i] = -1.0;
        act_memo[i] = -1;
    }
    int empty_a[1] = {0};
    double val = eval_policy_rec(empty_a, 0, rem_steps, prior, prior, L_hat, L_true, memo_hat, act_memo);
    free(memo_hat);
    free(act_memo);
    return val;
}
